use super::*;use crate::{json,Value,original_ambient::LavaSeed,original_lava::{self as lava,Draw,World}};use super::super::{State,BANKS};
fn hash(v:impl IntoIterator<Item=u8>)->u32{v.into_iter().fold(2166136261u32,|h,b|(h^u32::from(b)).wrapping_mul(16777619))}
fn hex(s:&str)->Vec<u8>{(0..s.len()).step_by(2).map(|i|u8::from_str_radix(&s[i..i+2],16).unwrap()).collect()}
fn n(r:&Value,k:&str)->i64{r[k].as_i64().unwrap()}
fn pair(r:&Value,k:&str)->[i16;2]{std::array::from_fn(|i|r[k][i].as_i64().unwrap()as i16)}
fn word(v:&mut Vec<u8>,n:i16){v.extend(n.to_le_bytes());}
fn queues(draws:&[Draw],camera:[i16;2])->(Vec<u8>,Vec<u8>){let(mut d,mut q)=(vec![],vec![]);for r in draws{let x=r.position[0].wrapping_sub(camera[0]);let y=r.position[1].wrapping_sub(camera[1]);word(&mut d,x);word(&mut d,y);if r.mode==0{word(&mut d,r.sprite);d.extend([r.palette as u8,r.offset as u8]);}else{word(&mut d,(q.len()/16)as i16);word(&mut d,-1);let mut a=vec![];word(&mut a,x);word(&mut a,y);word(&mut a,r.sprite);a.extend([r.palette as u8,r.mode]);a.extend([0,r.parameter,0,0,0,0,r.offset as u8,0]);q.extend(a);}}(d,q)}
struct Reference{view:View,multi:bool,resource:bool,value:u32,enabled:bool,clock:i16,audio:State,high:u32,rc:u32,wc:u32,dc:u32,mc:u32,order:String,stages:Vec<Vec<i64>>}
impl Reference{fn counter(&self)->u32{self.high|u32::from(self.audio.effect_counter as u16)}fn last(&self)->i16{self.audio.last[3][BANKS[3].iter().position(|d|d.id==122).unwrap()]}fn stage(&mut self,pc:i64){self.stages.push(vec![pc,i64::from(self.counter()),i64::from(self.last())]);}}
impl World for Reference{
 fn random(&mut self)->u32{panic!("positive-frame Source prefix has no gameplay RNG")}
 fn cosmetic_random(&mut self)->u32{assert!(!self.multi);self.rc+=1;self.order.push('R');self.value}
 fn multiplayer(&self)->bool{self.multi}fn view(&self)->View{self.view}fn bounds(&self)->[i16;2]{[1024,768]}fn native_world(&self)->u8{3}fn resource_present(&self)->bool{self.resource}fn terrain(&self,_:i16)->u8{panic!("no terrain leaf in recorded prefix")}fn scare(&mut self,_:[i16;2]){panic!("no scare leaf in recorded prefix")}fn burst(&mut self,_:[i16;2]){panic!("no burst leaf in recorded prefix")}
 fn sound(&mut self,c:lava::SoundChance){if !visible(c.point,self.view){return;}self.wc+=1;self.order.push('W');self.stage(0x46e6d0);if self.enabled{self.dc+=1;self.order.push('D');self.stage(0x46e660);}if self.audio.admit(3,122,self.clock,Gate::Enabled,self.enabled).is_some(){self.mc+=1;self.order.push('M');}self.stage(0x4069e4);}
}
#[test]fn lava_audio_matches784_actual_source_callbacks_queues_actor_bytes_stamps_and_counter(){
 let Some(path)=std::env::var_os("NATIVE_LAVA_AUDIO_TRACE")else{eprintln!("private NATIVE_LAVA_AUDIO_TRACE not supplied; numerical/Game tests still run");return;};let rows=std::fs::read_to_string(path).unwrap();let(mut count,mut signature)=(0,2166136261u32);
 for line in rows.lines(){let r:Value=serde_json::from_str(line).unwrap();let mut pool=lava::State::default();for(a,b)in pool.records.iter_mut().zip(hex(r["rawBefore"].as_str().unwrap()).chunks(60)){a.bytes.copy_from_slice(b);}let mut audio=State::default();let index=BANKS[3].iter().position(|d|d.id==122).unwrap();audio.last[3][index]=n(&r,"lastBefore")as i16;audio.effect_counter=n(&r,"counterBefore")as i16;let mut w=Reference{view:View{camera:pair(&r,"camera"),lower:pair(&r,"lower"),upper:pair(&r,"upper")},multi:n(&r,"multi")!=0,resource:n(&r,"profile")!=15,value:n(&r,"randValue")as u32,enabled:n(&r,"master")!=0,clock:n(&r,"clock")as i16,audio,high:n(&r,"counterBefore")as u32&0xffff0000,rc:0,wc:0,dc:0,mc:0,order:String::new(),stages:vec![]};
  assert_eq!(hash(pool.records.iter().flat_map(|p|p.bytes)),n(&r,"poolBefore")as u32);pool.advance(&mut w);let raw=pool.records.iter().take(n(&r,"actors")as usize).flat_map(|p|p.bytes).collect::<Vec<_>>();assert_eq!(raw,hex(r["raw"].as_str().unwrap()),"actor scenario{}",n(&r,"scenario"));let poolhash=hash(pool.records.iter().flat_map(|p|p.bytes));assert_eq!(poolhash,n(&r,"pool")as u32);let(d,q)=queues(&pool.draws,w.view.camera);assert_eq!(d,hex(r["queueD"].as_str().unwrap()));assert_eq!(q,hex(r["queueQ"].as_str().unwrap()));assert_eq!((w.rc,w.wc,w.dc,w.mc,i64::from(w.last()),i64::from(w.counter()),w.order.as_str()),(n(&r,"randCalls")as u32,n(&r,"wrapperCalls")as u32,n(&r,"descriptorCalls")as u32,n(&r,"mixes")as u32,n(&r,"last"),n(&r,"counter"),r["order"].as_str().unwrap()));assert_eq!(json!(w.stages),r["stages"]);
  for v in[n(&r,"scenario")as u32,n(&r,"tick")as u32,w.rc,w.wc,w.dc,w.mc,u32::from(w.last()as u16),w.counter(),poolhash,hash(d),hash(q)]{signature=(signature^v).wrapping_mul(16777619);}count+=1;
 }assert_eq!((count,signature),(784,1990701227));println!("LAVA_AUDIO784 signature={signature}");
}
fn game(mp:bool)->Game{let mut g=Game::new(0,1,50);g.map.original=true;g.map.world=1;g.multiplayer=mp;g.units.clear();g.ai_teams.clear();g.native_lava=Default::default();g.native_feedback.ui_clock=130;g.native_feedback.sound_enabled=1;g.native_view=Some(([0,0],[320,200]));views(&mut g,[true,true],[[0,0],[0,0]]);g}
fn views(g:&mut Game,masters:[bool;2],cameras:[[i16;2];2]){g.set_native_listener_settings(&json!({"0":{"soundEnabled":masters[0],"view":{"camera":cameras[0],"size":[320,200]},"hardwareContext":"1:0"},"1":{"soundEnabled":masters[1],"view":{"camera":cameras[1],"size":[320,200]},"hardwareContext":"1:0"}}));}
fn chance()->SoundChance{SoundChance{point:[150,160]}}
fn recipients(g:&Game)->Vec<u64>{g.events.iter().filter(|e|e["kind"]=="nativeSample"&&e["sampleId"]==122).map(|e|e["recipientTeam"].as_u64().unwrap_or(0)).collect()}
fn world(g:&Game)->Value{json!({"sim":g,"lava":g.native_lava.records.iter().map(|r|r.bytes.to_vec()).collect::<Vec<_>>(),"draws":g.native_lava_visuals(),"rng":g.original_rng.words,"crt":g.native_cosmetic_rng,"ticks":g.motion_tick,"production":g.production_clock,"fx":g.native_world_effects()})}
#[test]fn lava_audio_source_window_signed16_edges_and_nonzero_clip_are_separate_from_transport(){for x in[-129,-128,320,321]{assert_eq!(visible([x,0],View{camera:[0,0],lower:[0,0],upper:[320,200]}),(-128..=320).contains(&x));}for y in[-129,-128,200,201]{assert_eq!(visible([0,y],View{camera:[0,0],lower:[0,0],upper:[320,200]}),(-128..=200).contains(&y));}assert!(visible([-32766,32766],View{camera:[32760,-32760],lower:[0,0],upper:[320,200]}));assert!(!visible([-112,-144],View{camera:[0,0],lower:[17,-16],upper:[320,200]}));assert!(visible([-111,-144],View{camera:[0,0],lower:[17,-16],upper:[320,200]}));}
#[test]fn lava_audio_twenty_mp_actors_share_descriptor_but_not_listener_admission(){let mut g=game(true);for _ in 0..20{g.spawn_native_lava(LavaSeed{position:[150,160],template:0,size:2,interval:0});}let rng=g.original_rng.words;let crt=g.native_cosmetic_rng;g.update_native_lava();assert_eq!(g.native_lava_visuals().len(),20);assert_eq!(recipients(&g),[0,1]);assert_eq!((g.native_audio.effect_counter,g.native_listener_audio.guest_audio.effect_counter),(1,1));assert_eq!((g.original_rng.words,g.native_cosmetic_rng),(rng,crt));let e=&g.events;assert_ne!(e[0]["nativeAudioId"],e[1]["nativeAudioId"]);assert!(e.iter().all(|e|e["nativeHardwareAudioContext"]=="1:0"&&e["actorTeam"].is_null()&&e["clip"]=="VBIRD1"));}
#[test]fn lava_audio_mp_chance_lifts_only_audio_outside_canonical_world_view(){let(mut a,mut b)=(game(true),game(true));for g in [&mut a,&mut b]{g.native_view=Some(([700,700],[320,200]));g.spawn_native_lava(LavaSeed{position:[150,160],template:0,size:2,interval:0});}views(&mut a,[true,true],[[700,700],[0,0]]);views(&mut b,[false,false],[[0,0],[700,700]]);a.update_native_lava();b.update_native_lava();assert_eq!(recipients(&a),[1]);assert!(b.events.is_empty());assert!(a.native_lava_visuals().is_empty());a.events.clear();assert_eq!(world(&a),world(&b));}
#[test]fn lava_audio_sp_has_one_visible_crt_draw_even_when_muted_and_none_offscreen(){for enabled in[0,1]{let mut g=game(false);g.native_feedback.sound_enabled=enabled;g.spawn_native_lava(LavaSeed{position:[150,160],template:0,size:2,interval:0});let rng=g.original_rng.words;g.update_native_lava();assert_eq!(g.native_cosmetic_rng,2745024);assert_eq!(g.original_rng.words,rng);assert!(g.events.is_empty(),"seed1 CRT low7 is41, no chance");let mut g=game(false);g.native_view=Some(([700,700],[320,200]));g.spawn_native_lava(LavaSeed{position:[150,160],template:0,size:2,interval:0});g.update_native_lava();assert_eq!(g.native_cosmetic_rng,1);assert!(g.events.is_empty());}}
#[test]fn lava_audio_ui_pause_interval_wrap_settings_and_other_audio_owners_remain_independent(){for start in[130i16,32760,-10]{let mut g=game(true);g.native_feedback.ui_clock=start;g.native_audio.last[3].fill(start);g.native_listener_audio.guest_audio.last[3].fill(start);g.native_audio.opportunity_gate=255;g.native_audio.explosion_cycle=7;g.native_audio.late_build_clock=99;let before=world(&g);for _ in 0..119{g.step_native_ui_only(1./17.);g.emit_native_lava_audio(chance());}assert!(g.events.is_empty());g.step_native_ui_only(1./17.);g.emit_native_lava_audio(chance());assert_eq!(recipients(&g),[0,1]);assert_eq!((g.native_audio.effect_counter,g.native_listener_audio.guest_audio.effect_counter),(1,1));g.events.clear();assert_eq!(world(&g),before);assert_eq!((g.native_audio.opportunity_gate,g.native_audio.explosion_cycle,g.native_audio.late_build_clock),(255,7,99));views(&mut g,[false,false],[[700,700],[0,0]]);views(&mut g,[true,true],[[0,0],[0,0]]);g.emit_native_lava_audio(chance());assert!(g.events.is_empty(),"same stamp cannot replay after settings");}}
#[test]fn lava_audio_missing_view_never_falls_back_and_muted_calls_do_not_stamp(){let mut g=game(true);g.set_native_listener_settings(&json!({"0":{"soundEnabled":false,"view":{"camera":[0,0],"size":[320,200]},"hardwareContext":"1:0"},"1":{"soundEnabled":true}}));g.emit_native_lava_audio(chance());assert!(g.events.is_empty());assert_eq!((g.native_audio.effect_counter,g.native_listener_audio.guest_audio.effect_counter),(0,0));assert_eq!(g.native_listener_audio.guest_audio.opportunity_boundary,Some(super::super::spatial::Boundary::MissingListenerView(1)));views(&mut g,[false,true],[[0,0],[0,0]]);g.emit_native_lava_audio(chance());assert_eq!(recipients(&g),[1]);}
#[test]fn lava_audio_resource_world_delay_gates_remain_on_the_one_pool_callback(){let mut g=game(true);g.spawn_native_lava(LavaSeed{position:[150,160],template:0,size:2,interval:0});g.native_lava.records[0].set_word(24,2);for _ in 0..2{g.update_native_lava();assert!(g.events.is_empty());}g.update_native_lava();assert_eq!(recipients(&g),[0,1]);let mut g=game(true);g.map.world=0;assert_eq!(g.native_lava.spawn([150,160],0,2,0,0,true),None);g.update_native_lava();assert!(g.events.is_empty());}

#[test]fn lava_audio_sp_eligible_crt_uses_the_same_pre96_point_and_enabled_counter(){let mut g=game(false);g.native_cosmetic_rng=106;g.spawn_native_lava(LavaSeed{position:[150,160],template:0,size:2,interval:0});g.update_native_lava();assert_eq!(g.native_cosmetic_rng,25216389);assert_eq!(recipients(&g),[0]);assert_eq!(g.events[0]["clip"],"VBIRD1");assert!(g.events[0].get("nativeHardwareAudioContext").is_none());assert_eq!(g.native_audio.effect_counter,1);}
#[test]fn lava_audio_descriptor_timestamp_survives_sp_and_mp_mission_reinitialization(){for mp in[false,true]{let mut g=game(mp);g.emit_native_lava_audio(chance());let index=BANKS[3].iter().position(|d|d.id==122).unwrap();let before=g.native_audio.last[3][index];let guest=g.native_listener_audio.guest_audio.last[3][index];let counter=g.native_audio.effect_counter;let mission=json!({"map":g.map,"sectors":g.sectors,"buildings":g.buildings,"spawns":[],"crates":[]});g.apply_original(&mission).unwrap();assert_eq!(g.native_audio.last[3][index],before);assert_eq!(g.native_listener_audio.guest_audio.last[3][index],guest);assert_eq!(g.native_audio.effect_counter,counter);views(&mut g,[true,true],[[0,0],[0,0]]);g.events.clear();g.emit_native_lava_audio(chance());assert!(g.events.is_empty(),"mission/import is not a descriptor timestamp reset");}}
